('24794a46-8622-46c7-a3cb-84826cac8ec6'::uuid, 'd9fe8324-5259-4bd5-ac86-fa2934b55c69'::uuid, 1, $u$دل جانے پھر تجھ سے ٹوٹا ہے کیوں$u$, $u$تو ہی مگر اس کا مسیحا ہے کیوں$u$),
('22a33742-d24e-4a44-8d07-54beecdb6071'::uuid, 'd9fe8324-5259-4bd5-ac86-fa2934b55c69'::uuid, 2, $u$تیرے ملنے کی خوشی صرف ہم کو ہوئی$u$, $u$تیرے جانے پہ سارا شہر افسردہ ہے کیوں$u$),
('7077cf4e-ef9a-41df-ac25-cd1260ec9d73'::uuid, 'd9fe8324-5259-4bd5-ac86-fa2934b55c69'::uuid, 3, $u$وہ شے جو کبھی میسر ہی نہ ہوگی$u$, $u$ایک اسی پہ دل آتا ہے کیوں$u$),
('1bf51bdf-29ba-4c64-aef6-47157ca69af1'::uuid, 'd9fe8324-5259-4bd5-ac86-fa2934b55c69'::uuid, 4, $u$عریاں ہیں بدن کے داغ  اور زخم$u$, $u$غمِ دردِ دل اس قدر پوشیدہ ہے کیوں$u$),
('f5257cbc-323a-4127-929c-999c4684a2a1'::uuid, 'd9fe8324-5259-4bd5-ac86-fa2934b55c69'::uuid, 5, $u$جب کوئی راہبر، کوئی جادہِ منزل ہی نہیں$u$, $u$پھر تو آخر سفر کو چلتا ہے کیوں$u$),
('c1feafea-9f69-4260-b69e-5958ed4aee1d'::uuid, 'd9fe8324-5259-4bd5-ac86-fa2934b55c69'::uuid, 6, $u$میں نے بھرے فلک میں ایک جس کو چنا$u$, $u$وہی ستارہ نظر سے گمشدہ ہے کیوں$u$),
